DROP TABLE IF EXISTS `appointments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `appointments` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '预约ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `customer_id` bigint NOT NULL COMMENT '客户ID',
  `appointment_date` date NOT NULL COMMENT '预约日期',
  `appointment_time` time NOT NULL COMMENT '预约时间',
  `duration` int NOT NULL COMMENT '预计时长(分钟)',
  `total_amount` decimal(10,2) NOT NULL COMMENT '总金额',
  `status` enum('CONFIRMED','CHECKED_IN','COMPLETED','CANCELLED','NO_SHOW') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'CONFIRMED' COMMENT '状态',
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `rating` int DEFAULT NULL COMMENT '评分(1-5)',
  `review` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '评价',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'åˆ›å»ºæ—¶é—´',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'æ›´æ–°æ—¶é—´',
  `reminder_24h_sent` tinyint(1) DEFAULT '0' COMMENT '24å°æ—¶æé†’æ˜¯å¦å·²å‘é€',
  `reminder_30min_sent` tinyint(1) DEFAULT '0' COMMENT '30åˆ†é’Ÿæé†’æ˜¯å¦å·²å‘é€',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_date` (`tenant_id`,`appointment_date`),
  KEY `idx_customer_date` (`customer_id`,`appointment_date`),
  KEY `idx_staff_date` (`appointment_date`),
  KEY `idx_tenant_status` (`tenant_id`,`status`),
  KEY `idx_appointments_date_time` (`appointment_date`,`appointment_time`),
  KEY `idx_appointments_tenant_date` (`tenant_id`,`appointment_date`),
  CONSTRAINT `appointments_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=139 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='预约表';
