DROP TABLE IF EXISTS `business_notifications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `business_notifications` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint DEFAULT NULL COMMENT '租户ID（系统通知为NULL）',
  `notification_type` varchar(50) NOT NULL COMMENT '通知类型',
  `title` varchar(200) NOT NULL COMMENT '通知标题',
  `title_en` varchar(200) DEFAULT NULL,
  `title_zh` varchar(200) DEFAULT NULL,
  `content` text COMMENT '通知内容',
  `content_en` text,
  `content_zh` text,
  `level` varchar(20) DEFAULT 'INFO' COMMENT '通知级别：INFO/WARNING/SUCCESS/ERROR',
