DROP TABLE IF EXISTS `customer_package_usage_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `customer_package_usage_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `customer_id` bigint NOT NULL COMMENT '客户ID',
  `customer_package_id` bigint NOT NULL COMMENT '客户套餐ID',
  `package_id` bigint NOT NULL COMMENT '套餐模板ID',
  `package_name` varchar(200) NOT NULL COMMENT '套餐名称',
  `service_id` bigint NOT NULL COMMENT '服务ID',
  `service_name` varchar(200) NOT NULL COMMENT '服务名称',
  `appointment_id` bigint DEFAULT NULL COMMENT '关联的预约ID',
  `usage_type` varchar(20) DEFAULT 'DEDUCT' COMMENT '使用类型：DEDUCT-扣除, REFUND-退款, ADJUSTMENT-调整',
  `quantity` int DEFAULT '1' COMMENT '使用数量',
  `remaining_before` int NOT NULL COMMENT '使用前剩余次数',
  `remaining_after` int NOT NULL COMMENT '使用后剩余次数',
  `usage_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '使用时间',
  `staff_id` bigint DEFAULT NULL COMMENT '操作员工ID',
  `staff_name` varchar(100) DEFAULT NULL COMMENT '操作员工姓名',
  `notes` text COMMENT '备注说明',
  `verification_code_id` bigint DEFAULT NULL COMMENT '关联的验证码ID',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_customer` (`tenant_id`,`customer_id`),
  KEY `idx_customer_package` (`customer_package_id`),
  KEY `idx_package` (`package_id`),
  KEY `idx_service` (`service_id`),
  KEY `idx_appointment` (`appointment_id`),
  KEY `idx_usage_date` (`usage_date`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_verification_code` (`verification_code_id`)
) ENGINE=InnoDB AUTO_INCREMENT=56 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='客户套餐使用记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

