--
-- Table structure for table `customer_packages`
--

DROP TABLE IF EXISTS `customer_packages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `customer_packages` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'Customer package ID',
  `tenant_id` bigint NOT NULL COMMENT 'Tenant ID',
  `customer_id` bigint NOT NULL COMMENT 'Primary customer ID (purchaser)',
  `package_id` bigint NOT NULL COMMENT 'Package template ID',
  `purchase_date` date NOT NULL COMMENT 'Purchase date',
  `expiration_date` date NOT NULL COMMENT 'Expiration date',
  `purchase_price` decimal(10,2) NOT NULL COMMENT 'Actual paid price',
  `payment_status` enum('PENDING','PAID','REFUNDED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'PAID' COMMENT 'Payment status',
  `usage_details` json NOT NULL COMMENT 'Service usage tracking (JSON array)',
  `status` enum('ACTIVE','COMPLETED','EXPIRED','CANCELLED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'ACTIVE' COMMENT 'Package status',
  `first_used_at` datetime DEFAULT NULL COMMENT 'First usage time',
  `last_used_at` datetime DEFAULT NULL COMMENT 'Last usage time',
  `completed_at` datetime DEFAULT NULL COMMENT 'Completion time',
  `shared_users` json DEFAULT NULL COMMENT 'Users who can use this package (JSON array)',
  `is_gift` tinyint(1) DEFAULT '0' COMMENT 'Is gift',
  `gifted_by_customer_id` bigint DEFAULT NULL COMMENT 'Gift giver customer ID',
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Admin notes',
  `refund_amount` decimal(10,2) DEFAULT NULL COMMENT 'Refund amount',
  `refund_date` date DEFAULT NULL COMMENT 'Refund date',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Created time',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Updated time',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_customer` (`tenant_id`,`customer_id`),
  KEY `idx_package_id` (`package_id`),
  KEY `idx_status` (`status`),
  KEY `idx_expiration` (`expiration_date`,`status`),
  KEY `fk_customer_packages_customer` (`customer_id`),
  CONSTRAINT `fk_customer_packages_customer` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_customer_packages_package` FOREIGN KEY (`package_id`) REFERENCES `packages` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Customer package purchases and usage';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `customer_packages`
--

