/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `customers` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '客户ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `first_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '名',
  `last_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '姓',
  `country_code` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT '+1-CA' COMMENT '国家码（如 +1-CA, +1-US, +86）',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '手机号',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮箱',
  `address` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '地址',
  `date_of_birth` date DEFAULT NULL COMMENT '生日',
  `gender` enum('MALE','FEMALE','OTHER','PREFER_NOT_TO_SAY') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '性别',
  `membership_level` enum('REGULAR','SILVER','GOLD','PLATINUM') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'REGULAR' COMMENT '会员等级',
  `points` int DEFAULT '0' COMMENT '积分',
  `total_spent` decimal(10,2) DEFAULT '0.00' COMMENT '总消费',
  `status` enum('ACTIVE','INACTIVE') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'ACTIVE' COMMENT '状态',
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `allergies` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '过敏信息',
  `communication_preference` enum('SMS','EMAIL','PHONE','BOTH') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'SMS' COMMENT '沟通偏好',
  `last_visit_date` datetime DEFAULT NULL COMMENT '最后访问日期',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'åˆ›å»ºæ—¶é—´',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'æ›´æ–°æ—¶é—´',
  `created_by` bigint DEFAULT NULL COMMENT '创建人',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_phone` (`tenant_id`,`phone`),
  UNIQUE KEY `uk_tenant_email` (`tenant_id`,`email`),
  KEY `idx_tenant_id` (`tenant_id`),
  KEY `idx_phone` (`phone`),
  KEY `idx_email` (`email`),
  KEY `idx_status` (`status`),
  KEY `idx_last_visit_date` (`last_visit_date`),
  KEY `idx_customers_tenant_phone` (`tenant_id`,`phone`),
  KEY `idx_customers_tenant_email` (`tenant_id`,`email`)
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='客户表';
