CREATE TABLE `packages` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'Package ID',
  `tenant_id` bigint NOT NULL COMMENT 'Tenant ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Package name',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Package description',
  `icon` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Icon',
  `color` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Display color',
  `services` json NOT NULL COMMENT 'Services included with usage counts (JSON array)',
  `original_price` decimal(10,2) NOT NULL COMMENT 'Original total price',
  `package_price` decimal(10,2) NOT NULL COMMENT 'Discounted package price',
  `discount_percentage` decimal(5,2) DEFAULT NULL COMMENT 'Discount percentage',
  `validity_days` int NOT NULL DEFAULT '365' COMMENT 'Validity period in days',
  `max_shared_users` int DEFAULT '1' COMMENT 'Max users who can share (1=individual, 2+=shareable)',
  `terms` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Terms and conditions',
  `status` enum('ACTIVE','INACTIVE') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'ACTIVE' COMMENT 'Status',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Created time',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Updated time',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_status` (`tenant_id`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Package templates';
