INSERT INTO `notification_logs` (`id`, `tenant_id`, `template_code`, `type`, `recipient`, `subject`, `content`, `status`, `business_id`, `business_type`, `error_message`, `retry_count`, `created_at`, `sent_at`) VALUES (1,1,'PASSWORD_RESET','EMAIL','merchant@merchant.com','Password Reset Request','<html>\n<body style=\"font-family: Arial, sans-serif; line-height: 1.6; color: #333;\">\n    <div style=\"max-width: 600px; margin: 0 auto; padding: 20px;\">\n        <h2 style=\"color: #667eea;\">Password Reset Request</h2>\n\n        <p>Dear 商户管理员,</p>\n\n        <p>We received a request to reset your password. Click the button below to reset it:</p>\n\n        <div style=\"text-align: center; margin: 30px 0;\">\n            <a href=\"http://localhost:3000/reset-password?token=4d1f6f6d-e937-4244-89dd-8647f5e61cd9\"\n               style=\"background-color: #667eea; color: white; padding: 12px 30px;\n                      text-decoration: none; border-radius: 5px; display: inline-block;\">\n                Reset Password\n            </a>\n        </div>\n\n        <p>Or copy and paste this link into your browser:</p>\n        <p style=\"background-color: #f4f4f4; padding: 10px; border-radius: 5px; word-break: break-all;\">\n            http://localhost:3000/reset-password?token=4d1f6f6d-e937-4244-89dd-8647f5e61cd9\n        </p>\n\n        <p><strong>This link will expire in 24 hours.</strong></p>\n\n        <p>If you didn\'t request a password reset, please ignore this email or contact support if you have concerns.</p>\n\n        <hr style=\"border: none; border-top: 1px solid #eee; margin: 30px 0;\">\n\n        <p style=\"font-size: 12px; color: #999;\">\n            This is an automated email, please do not reply.\n        </p>\n    </div>\n</body>\n</html>\n','SENT',NULL,'PASSWORD_RESET',NULL,0,'2025-10-25 07:42:31','2025-10-25 07:42:32'),(2,1,'APPOINTMENT_CANCELLED','EMAIL','li@example.com','预约取消通知 - 美丽人生美容院','<html><body>\n<h2>预约取消通知</h2>\n<p>尊敬的 李 先生，</p>\n<p>您的预约已成